 public void PairedColumnsRemainRoleScoped(string key,string original,string sha,string claimant,string owner,string reference,string vrm,string make,string model,string incident,string instruction,string vat){var root=Root();var text=File.ReadAllText(Path.Combine(root,"astra_output","reports","principals","ALS","sources",$"{key}.txt"));Assert.Equal(sha,Convert.ToHexStringLower(SHA256.HashData(File.ReadAllBytes(Path.Combine(root,"principal-docs","original-mapper-instruction-corpus",original)))));var result=new AlsInstructionExtractionPolicy().Extract(new(IntakeSourceReadStatus.Readable,[new(IntakeEvidenceSource.DocumentContent,"ALS instruction",text)],[],[],false),new(2026,9,6,12,0,0,TimeSpan.Zero),new("ALS",AlsInstructionExtractionPolicy.DocumentProfileKeyValue,1));var d=Assert.IsType<InstructionDraft>(result.InstructionDraft);Assert.Equal(claimant,d.ClaimantName);Assert.Equal(owner,F(result,"Vehicle owner"));Assert.Equal(reference,d.ClaimNumber);Assert.Equal(vrm,d.VehicleRegistration);Assert.Equal(make,d.VehicleMake);Assert.Equal(model,d.VehicleModel);Assert.Equal(incident,D(d.DateOfIncident));Assert.Equal(instruction,D(d.InstructionDate));Assert.Equal(vat,d.VatStatus);Assert.Null(d.InspectionDate);Assert.DoesNotContain(result.Fields,x=>x.Name.Contains("salvage",StringComparison.OrdinalIgnoreCase));}
 static string?F(InstructionExtractionResult r,string n)=>Assert.Single(r.Fields,x=>x.Name==n).SuggestedValue;static string?D(DateOnly?d)=>d?.ToString("yyyy-MM-dd",System.Globalization.CultureInfo.InvariantCulture);static string Root()=>Environment.GetEnvironmentVariable("PEGASUS_REFERENCE_PACK_ROOT")??throw new InvalidOperationException();}
